1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Scores an owner's membership. Points start at 0 and add 2 for a present email, 1 when the
9	 * namesake count is 0, 2 for a household of 3 or more and 3 for tenure of at least one
10	 * elapsed fiscal year. The numeric level maps those points as 1 (0-1), 2 (2-3), 3 (4-5) and
11	 * 4 (6 or more).
12	 */
13	public final class MembershipLevel {
14	
15	    private MembershipLevel() {
16	    }
17	
18	    public static int points(Owner owner, int namesakeCount, int householdSize) {
19	        int points = 0;
20	        if (owner.getEmail() != null) {
21	            points += 2;
22	        }
23	        if (namesakeCount == 0) {
24	            points += 1;
25	        }
26	        if (householdSize >= 3) {
27	            points += 2;
28	        }
29	        if (hasTenure(owner)) {
30	            points += 3;
31	        }
32	        return points;
33	    }
34	
35	    public static int level(int points) {
36	        return Math.min(points / 2 + 1, 4);
37	    }
38	
39	    private static boolean hasTenure(Owner owner) {
40	        LocalDate registration = owner.getRegistrationDate();
41	        return registration != null
42	                && FiscalYear.of(LocalDate.now()) - FiscalYear.of(registration) >= 1;
43	    }
44	}
