19	        int membershipLevel = MembershipCap.apply(owner, MembershipLevel.level(membershipPoints), ownerRepository);
20	        dto.setMembershipLevel(membershipLevel);
21	        dto.setOwnerSegment(OwnerSegment.of(membershipLevel, owner));
22	        dto.setContactPreference(owner.getEmail() != null ? "EMAIL" : "PHONE");
23	        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, ownerRepository);
24	        dto.setPossibleDuplicate(possibleDuplicateOf != null);
25	        dto.setPossibleDuplicateOf(possibleDuplicateOf);
26	        dto.setSelfLink("/api/owners/" + owner.getId());
27	        long cityOwners = ownerRepository.findAll().stream()
28	                .filter(other -> owner.getCity() != null && owner.getCity().equalsIgnoreCase(other.getCity()))
29	                .count();
30	        dto.setCapacityWarning(cityOwners >= 40 && cityOwners < 50);
